// Duration-weighted assignment of test files to CI shards.
//
// CI runs the suite as N parallel shards; each browser receives its shard
// coordinates as `shard` / `shardCount` query params and must pick a subset
// of the `import.meta.glob` test-module map to load (see test-helper.js).
// Test files vary in cost by two orders of magnitude, so a count-based
// split leaves some shards running many times longer than others; this
// assignment instead bin-packs files by their historical duration
// (tests/test-module-timings.json, regenerated by
// scripts/generate-test-module-timings.mjs).
//
// Every browser in a run computes the assignment for ALL shards from the
// same inputs and keeps only its own bucket, so the algorithm must be
// deterministic: files are sorted (by weight descending, path ascending)
// and greedily assigned to the lightest bucket, with ties broken by bucket
// index. Files absent from the timings data get the median known weight,
// so a new test file runs — on exactly one shard — without the timings
// file needing regeneration.

export function selectShardModules(
  moduleIds: string[],
  shard: number,
  shardCount: number,
  timings: Record<string, number>,
): string[] {
  if (!Number.isInteger(shard) || !Number.isInteger(shardCount)) {
    throw new Error(
      `shard and shardCount must be integers (got shard=${shard}, shardCount=${shardCount})`,
    );
  }
  if (shardCount < 1 || shard < 1 || shard > shardCount) {
    throw new Error(
      `shard must be in 1..shardCount (got shard=${shard}, shardCount=${shardCount})`,
    );
  }

  let knownWeights = Object.values(timings).sort((a, b) => a - b);
  let defaultWeight = knownWeights.length
    ? knownWeights[Math.floor(knownWeights.length / 2)]
    : 1;
  let weightOf = (id: string) => timings[id] ?? defaultWeight;

  let ordered = [...moduleIds].sort((a, b) => {
    let diff = weightOf(b) - weightOf(a);
    if (diff !== 0) {
      return diff;
    }
    return a < b ? -1 : a > b ? 1 : 0;
  });

  let buckets: { weight: number; ids: string[] }[] = Array.from(
    { length: shardCount },
    () => ({ weight: 0, ids: [] }),
  );
  for (let id of ordered) {
    let lightest = buckets[0];
    for (let bucket of buckets) {
      if (bucket.weight < lightest.weight) {
        lightest = bucket;
      }
    }
    lightest.ids.push(id);
    lightest.weight += weightOf(id);
  }

  return buckets[shard - 1].ids;
}
